<?php
namespace Modules\Ran\Http\Controllers;
use Modules\Ran\Entities\{ProductionOrder,Item,Design,Artisan,StockLot};use Modules\Ran\Http\Requests\ProductionOrderRequest;use Modules\Ran\Services\ProductionService;use Modules\Ran\Integrations\CustomerIntegrationService;use Modules\Ran\Integrations\SupplierIntegrationService;
class ProductionController extends RanController {public function index(){return view('ran::production.index',array_merge($this->pageOptions(),['orders'=>ProductionOrder::with('artisan')->latest('order_date')->latest('id')->paginate(25)]));} private function options(){return array_merge($this->pageOptions(),['items'=>Item::where('is_active',1)->pluck('name','id'),'designs'=>Design::where('is_active',1)->pluck('name','id'),'artisans'=>Artisan::where('is_active',1)->pluck('name','id'),'customers'=>class_exists(CustomerIntegrationService::class)?app(CustomerIntegrationService::class)->dropdown():collect(),'suppliers'=>class_exists(SupplierIntegrationService::class)?app(SupplierIntegrationService::class)->dropdown():collect()]);} public function create(){return view('ran::production.form',array_merge($this->options(),['order'=>null]));} public function store(ProductionOrderRequest $request,ProductionService $service){$order=$service->create($request->validated());return $this->success('Production order created.','ran.production.show',[$order]);} public function show(ProductionOrder $production){return view('ran::production.show',array_merge($this->pageOptions(),['order'=>$production->load(['lines.item','artisan','materialIssues.lines','receipts.lines']),'lots'=>StockLot::with('item')->where('stock_status','available')->get(),'items'=>Item::where('is_active',1)->pluck('name','id')]));} public function edit(ProductionOrder $production){return view('ran::production.form',array_merge($this->options(),['order'=>$production->load('lines')]));} public function update(ProductionOrderRequest $request,ProductionOrder $production,ProductionService $service){$service->update($production,$request->validated());return $this->success('Production order updated.','ran.production.show',[$production]);} public function approve(ProductionOrder $production,ProductionService $service){$service->approve($production);return back()->with('status','Production order approved.');}}
